@Override
public int hashCode() {
    int result = maxDepth;
    result = 31 * result + (throwOnMaxDepth ? 1 : 0);
    result = 31 * result + maxCount;
    result = 31 * result + (throwOnMaxCount ? 1 : 0);
    return result;
}
